function transform (message, context) {
  const periods = Array.isArray(message && message.payload) ? message.payload : [];
  const today = new Date().toISOString().slice(0, 10);
  const active = periods.filter(p => {
    const start = p.startOn ? p.startOn.slice(0, 10) : null;
    const end = p.endOn ? p.endOn.slice(0, 10) : null;
    if (!start || !end) return false;
    return start <= today && today <= end;
  });
  return { payload: active };
}

function transform (message, context) {
  const periods = Array.isArray(message && message.payload) ? message.payload : [];
  const data = periods.map(p => ({
    id: p.id,
    code: p.code,
    title: p.title,
    startOn: p.startOn,
    endOn: p.endOn,
    category: p.category && p.category.type
  }));
  return { payload: data };
}
